fn two_sum(nums: &[i32], target: i32) -> Vec<usize> {
    use std::collections::HashMap;
    let mut seen = HashMap::new();
    for (i, &n) in nums.iter().enumerate() {
        if let Some(&j) = seen.get(&(target - n)) { return vec![j, i];
        } seen.insert(n, i);
    } vec![] }

fn is_valid_parens(s: &str) -> bool { let mut stack = Vec::new();
    for c in s.chars() { match c { '(' | '[' | '{' => stack.push(c),
            ')' => if stack.pop() != Some('(') { return false },
            ']' => if stack.pop() != Some('[') { return false },
            '}' => if stack.pop() != Some('{') { return false },
            _ => {} } }
    stack.is_empty() }

#[derive(PartialEq, Eq, Clone, Debug)]
pub struct ListNode { pub val: i32, pub next: Option<Box<ListNode>>,
} pub fn reverse_list(head: Option<Box<ListNode>>) -> Option<Box<ListNode>> { let mut prev = None;
    let mut cur = head;
    while let Some(mut node) = cur { cur = node.next.take();
        node.next = prev;
        prev = Some(node); } prev }

fn max_subarray(nums: &[i32]) -> i32 {
    let mut best = nums[0];
    let mut cur = nums[0];
    for &n in &nums[1..] { cur = n.max(cur + n);
        best = best.max(cur);
    } best
}

#[derive(PartialEq, Eq, Clone, Debug)]
pub struct ListNode { pub val: i32, pub next: Option<Box<ListNode>>, } pub fn merge_two_lists(
    a: Option<Box<ListNode>>, b: Option<Box<ListNode>>, ) -> Option<Box<ListNode>> { match (a, b) { (None, None) => None,
        (Some(node), None) | (None, Some(node)) => Some(node),
        (Some(mut x), Some(mut y)) => { if x.val <= y.val { x.next = merge_two_lists(x.next.take(), Some(y));
                Some(x) } else { y.next = merge_two_lists(Some(x), y.next.take());
                Some(y) } } } }

fn max_profit(prices: &[i32]) -> i32 {
    let mut best = 0;
    let mut low = prices[0];
    for &price in prices { best = best.max(price - low);
        low = low.min(price);
    } best
}

fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s.chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();
    chars == chars.iter().rev().copied().collect::<Vec<char>>()
}

fn climb_stairs(n: i32) -> i32 { let mut a = 1;
    let mut b = 1;
    for _ in 0..n - 1 { let next = a + b;
        a = b;
        b = next;
    } b
}

fn binary_search(arr: &[i32], target: i32) -> Option<usize> { let mut lo = 0;
    let mut hi = arr.len();
    while lo < hi { let mid = lo + (hi - lo) / 2;
        if arr[mid] == target { return Some(mid);
        } else if arr[mid] < target { lo = mid + 1;
        } else { hi = mid; } }
    None }

fn single_number(nums: &[i32]) -> i32 {
    nums.iter().fold(0, |acc, &n| acc ^ n)
}

fn contains_duplicate(nums: &[i32]) -> bool {
    use std::collections::HashSet;
    let mut seen = HashSet::new();
    for &n in nums { if !seen.insert(n) { return true;
        } }
    false
}

fn majority_element(nums: &[i32]) -> i32 {
    let mut count = 0;
    let mut candidate = 0;
    for &n in nums {
        if count == 0 { candidate = n;
        } count += if n == candidate { 1 } else { -1 }; } candidate
}

fn move_zeroes(nums: &mut Vec<i32>) { let mut write = 0;
    for read in 0..nums.len() {
        if nums[read] != 0 { nums[write] = nums[read];
            write += 1;
        } }
    for i in write..nums.len() { nums[i] = 0;
    } }

fn product_except_self(nums: &[i32]) -> Vec<i32> { let n = nums.len();
    let mut res = vec![1; n];
    for i in 1..n { res[i] = res[i - 1] * nums[i - 1];
    } let mut right = 1;
    for i in (0..n).rev() { res[i] *= right;
        right *= nums[i];
    } res }

fn merge_intervals(intervals: &mut Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    intervals.sort_by_key(|interval| interval[0]);
    let mut merged: Vec<Vec<i32>> = Vec::new();
    for interval in intervals.iter() { match merged.last_mut() {
            Some(last) if interval[0] <= last[1] => { last[1] = last[1].max(interval[1]);
            } _ => merged.push(interval.clone()), } }
    merged }

fn group_anagrams(strs: &[String]) -> Vec<Vec<String>> { use std::collections::HashMap;
    let mut groups: HashMap<String, Vec<String>> = HashMap::new();
    for s in strs { let mut chars: Vec<char> = s.chars().collect();
        chars.sort();
        let key: String = chars.into_iter().collect();
        groups.entry(key).or_default().push(s.clone());
    } groups.into_values().collect() }

fn longest_common_prefix(strs: &[String]) -> String {
    if strs.is_empty() { return String::new();
    } let mut prefix = strs[0].clone();
    for s in &strs[1..] {
        while !s.starts_with(&prefix) { prefix.pop();
            if prefix.is_empty() { return prefix;
            } } } prefix }

fn roman_to_int(s: &str) -> i32 { fn value(c: char) -> i32 { match c { 'I' => 1, 'V' => 5, 'X' => 10, 'L' => 50,
            'C' => 100, 'D' => 500, 'M' => 1000, _ => 0, } }
    let chars: Vec<char> = s.chars().collect();
    let mut total = 0;
    for i in 0..chars.len() { let current = value(chars[i]);
        if i + 1 < chars.len() && current < value(chars[i + 1]) { total -= current; } else { total += current; } }
    total }

fn is_palindrome_number(x: i32) -> bool {
    if x < 0 { return false;
    } let (mut original, mut reversed) = (x, 0);
    while original > 0 { reversed = reversed * 10 + original % 10;
        original /= 10;
    } reversed == x
}

fn plus_one(digits: &mut Vec<i32>) -> Vec<i32> {
    for i in (0..digits.len()).rev() { if digits[i] < 9 { digits[i] += 1;
            return digits.clone();
        } digits[i] = 0;
    } let mut result = vec![1];
    result.extend(digits.iter());
    result }

fn remove_duplicates(nums: &mut Vec<i32>) -> usize {
    let mut write = 0;
    for read in 0..nums.len() {
        if write == 0 || nums[read] != nums[write - 1] {
            nums[write] = nums[read];
            write += 1; } }
    write }

fn rotate_array(nums: &mut Vec<i32>, k: usize) {
    let n = nums.len();
    if n == 0 {
        return;
    } let k = k % n;
    nums.rotate_right(k);
}

fn missing_number(nums: &[i32]) -> i32 {
    let n = nums.len() as i32;
    let expected = n * (n + 1) / 2;
    expected - nums.iter().sum::<i32>()
}

fn fizz_buzz(n: i32) -> Vec<String> { (1..=n)
        .map(|i| match (i % 3, i % 5) { (0, 0) => "FizzBuzz".to_string(),
            (0, _) => "Fizz".to_string(),
            (_, 0) => "Buzz".to_string(),
            _ => i.to_string(),
        }) .collect()
}

fn is_power_of_two(n: i32) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

fn hamming_weight(mut n: u32) -> u32 {
    let mut count = 0;
    while n != 0 {
        count += n & 1;
        n >>= 1;
    } count
}

fn reverse_string(s: &str) -> String {
    s.chars().rev().collect()
}

fn reverse_integer(x: i32) -> i32 { let mut result: i64 = 0;
    let mut n = x as i64;
    while n != 0 { result = result * 10 + n % 10;
        n /= 10;
    } if result < i32::MIN as i64 || result > i32::MAX as i64 {
        return 0;
    } result as i32 }

fn length_of_last_word(s: &str) -> usize {
    s.split_whitespace().last().map_or(0, |word| word.len())
}

fn str_str(haystack: &str, needle: &str) -> i32 {
    if needle.is_empty() {
        return 0;
    } match haystack.find(needle) {
        Some(index) => index as i32,
        None => -1,
    } }

fn add_binary(a: &str, b: &str) -> String { let (mut i, mut j) = (a.len() as i32 - 1, b.len() as i32 - 1);
    let (a, b) = (a.as_bytes(), b.as_bytes()); let mut carry = 0; let mut result = Vec::new();
    while i >= 0 || j >= 0 || carry > 0 { let mut total = carry;
        if i >= 0 { total += (a[i as usize] - b'0') as i32;
            i -= 1; } if j >= 0 { total += (b[j as usize] - b'0') as i32;
            j -= 1; } result.push((b'0' + (total % 2) as u8) as char);
        carry = total / 2; } result.iter().rev().collect() }

fn my_sqrt(x: i32) -> i32 { if x < 2 { return x;
    } let (mut lo, mut hi, mut answer) = (1, x / 2, 0);
    while lo <= hi { let mid = lo + (hi - lo) / 2;
        if mid as i64 * mid as i64 <= x as i64 { answer = mid;
            lo = mid + 1;
        } else { hi = mid - 1; } }
    answer }

fn title_to_number(column_title: &str) -> i32 {
    let mut result = 0;
    for c in column_title.chars() {
        result = result * 26 + (c as i32 - 'A' as i32 + 1);
    }
    result
}

fn is_happy(mut n: i32) -> bool { use std::collections::HashSet;
    let mut seen = HashSet::new();
    while n != 1 && seen.insert(n) { let mut total = 0;
        while n > 0 { let digit = n % 10;
            total += digit * digit;
            n /= 10; } n = total;
    } n == 1 }

fn is_isomorphic(s: &str, t: &str) -> bool { use std::collections::HashMap;
    let mut forward = HashMap::new();
    let mut backward = HashMap::new();
    for (a, b) in s.chars().zip(t.chars()) { if forward.get(&a).map_or(false, |&v| v != b) { return false;
        } if backward.get(&b).map_or(false, |&v| v != a) { return false;
        } forward.insert(a, b);
        backward.insert(b, a); } true }

fn word_pattern(pattern: &str, s: &str) -> bool { use std::collections::HashMap;
    let words: Vec<&str> = s.split_whitespace().collect();
    let letters: Vec<char> = pattern.chars().collect();
    if letters.len() != words.len() { return false; } let mut forward = HashMap::new();
    let mut backward = HashMap::new();
    for (&c, word) in letters.iter().zip(words.iter()) { if forward.get(&c).map_or(false, |&v| v != *word) { return false; } if backward.get(*word).map_or(false, |&v| v != c) { return false; } forward.insert(c, *word);
        backward.insert(*word, c); } true }

fn intersection(nums1: &[i32], nums2: &[i32]) -> Vec<i32> {
    use std::collections::HashSet;
    let set: HashSet<i32> = nums1.iter().copied().collect();
    let mut result = HashSet::new();
    for &n in nums2 { if set.contains(&n) { result.insert(n);
        } }
    result.into_iter().collect() }

fn sorted_squares(nums: &[i32]) -> Vec<i32> {
    let mut result: Vec<i32> = nums.iter().map(|n| n * n).collect();
    result.sort();
    result
}

pub struct TreeNode { pub val: i32,
    pub left: Option<Box<TreeNode>>,
    pub right: Option<Box<TreeNode>>,
} fn max_depth(root: &Option<Box<TreeNode>>) -> i32 {
    match root { None => 0,
        Some(node) => 1 + max_depth(&node.left).max(max_depth(&node.right)),
    } }

pub struct TreeNode { pub val: i32,
    pub left: Option<Box<TreeNode>>,
    pub right: Option<Box<TreeNode>>,
} fn invert_tree(root: &mut Option<Box<TreeNode>>) {
    if let Some(node) = root { std::mem::swap(&mut node.left, &mut node.right);
        invert_tree(&mut node.left);
        invert_tree(&mut node.right); } }

pub struct TreeNode { pub val: i32, pub left: Option<Box<TreeNode>>, pub right: Option<Box<TreeNode>>,
} fn mirror(a: &Option<Box<TreeNode>>, b: &Option<Box<TreeNode>>) -> bool { match (a, b) { (None, None) => true,
        (Some(x), Some(y)) => { x.val == y.val
                && mirror(&x.left, &y.right)
                && mirror(&x.right, &y.left) } _ => false, } }
fn is_symmetric(root: &Option<Box<TreeNode>>) -> bool { match root { None => true,
        Some(node) => mirror(&node.left, &node.right), } }

pub struct TreeNode { pub val: i32, pub left: Option<Box<TreeNode>>, pub right: Option<Box<TreeNode>>,
} fn depth(node: &Option<Box<TreeNode>>, best: &mut i32) -> i32 { match node { None => 0, Some(n) => { let left = depth(&n.left, best);
            let right = depth(&n.right, best);
            *best = (*best).max(left + right);
            1 + left.max(right) } } } fn diameter_of_binary_tree(root: &Option<Box<TreeNode>>) -> i32 { let mut best = 0;
    depth(root, &mut best);
    best }

pub struct TreeNode { pub val: i32,
    pub left: Option<Box<TreeNode>>,
    pub right: Option<Box<TreeNode>>, } fn height(node: &Option<Box<TreeNode>>) -> i32 { match node { None => 0,
        Some(n) => { let left = height(&n.left);
            let right = height(&n.right);
            if left < 0 || right < 0 || (left - right).abs() > 1 { -1 } else { 1 + left.max(right) } } } }
fn is_balanced(root: &Option<Box<TreeNode>>) -> bool { height(root) >= 0 }

pub struct TreeNode { pub val: i32,
    pub left: Option<Box<TreeNode>>,
    pub right: Option<Box<TreeNode>>,
} fn has_path_sum(root: &Option<Box<TreeNode>>, target: i32) -> bool { match root { None => false,
        Some(node) => { if node.left.is_none() && node.right.is_none() { return node.val == target;
            } has_path_sum(&node.left, target - node.val)
                || has_path_sum(&node.right, target - node.val) } } }

pub struct TreeNode { pub val: i32, pub left: Option<Box<TreeNode>>,
    pub right: Option<Box<TreeNode>>, } fn lowest_common_ancestor<'a>(
    root: &'a Option<Box<TreeNode>>, p: i32, q: i32,
) -> Option<&'a TreeNode> { let mut current = root.as_deref();
    while let Some(node) = current { if p < node.val && q < node.val { current = node.left.as_deref();
        } else if p > node.val && q > node.val { current = node.right.as_deref(); } else { return Some(node); } }
    None }

fn search_insert(nums: &[i32], target: i32) -> usize { let mut lo = 0;
    let mut hi = nums.len();
    while lo < hi { let mid = lo + (hi - lo) / 2;
        if nums[mid] < target { lo = mid + 1;
        } else { hi = mid;
        } }
    lo }

fn two_sum_sorted(numbers: &[i32], target: i32) -> Vec<usize> { let mut left = 0;
    let mut right = numbers.len() - 1;
    while left < right { let total = numbers[left] + numbers[right];
        if total == target { return vec![left + 1, right + 1];
        } else if total < target { left += 1;
        } else { right -= 1; } }
    vec![] }

fn length_of_longest_substring(s: &str) -> usize { use std::collections::HashMap;
    let mut last = HashMap::new();
    let mut start = 0;
    let mut best = 0;
    for (i, c) in s.chars().enumerate() { if let Some(&index) = last.get(&c) { if index >= start { start = index + 1; } }
        last.insert(c, i);
        best = best.max(i - start + 1); } best }

fn max_area(height: &[i32]) -> i32 { let mut left = 0;
    let mut right = height.len() - 1;
    let mut best = 0;
    while left < right { best = best.max(height[left].min(height[right]) * (right - left) as i32);
        if height[left] < height[right] { left += 1;
        } else { right -= 1; } }
    best }
